create extension if not exists pgcrypto;
create table if not exists public.organizations (id uuid primary key default gen_random_uuid(), name text not null check (char_length(trim(name)) between 2 and 120), created_at timestamptz not null default now());
create table if not exists public.memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check (role in ('OWNER','MEMBER')), status text not null default 'ACTIVE' check (status in ('ACTIVE','INACTIVE')), created_at timestamptz not null default now(), unique(organization_id,user_id));
create table if not exists public.investment_projects (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, name text not null check (char_length(trim(name)) between 2 and 160), internal_reference text, sector text not null default 'REAL_ESTATE' check(sector='REAL_ESTATE'), lifecycle_state text not null default 'DRAFT' check(lifecycle_state='DRAFT'), reporting_currency text not null default 'EGP' check(reporting_currency='EGP'), description text, created_at timestamptz not null default now(), unique(id,organization_id));
create table if not exists public.audit_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, actor_id uuid not null references auth.users(id) on delete restrict, event_type text not null, entity_type text not null, entity_id uuid not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists projects_org_idx on public.investment_projects(organization_id); create index if not exists memberships_active_idx on public.memberships(user_id,organization_id) where status='ACTIVE';
alter table public.organizations enable row level security; alter table public.memberships enable row level security; alter table public.investment_projects enable row level security; alter table public.audit_events enable row level security;
alter table public.organizations force row level security; alter table public.memberships force row level security; alter table public.investment_projects force row level security; alter table public.audit_events force row level security;
create or replace function public.is_active_member(p_organization_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$ select exists(select 1 from public.memberships m where m.organization_id=p_organization_id and m.user_id=auth.uid() and m.status='ACTIVE') $$;
revoke all on function public.is_active_member(uuid) from public, anon; grant execute on function public.is_active_member(uuid) to authenticated;
create policy organization_read on public.organizations for select to authenticated using (public.is_active_member(id));
create policy membership_read on public.memberships for select to authenticated using (public.is_active_member(organization_id));
create policy project_read on public.investment_projects for select to authenticated using (public.is_active_member(organization_id));
create policy audit_read on public.audit_events for select to authenticated using (public.is_active_member(organization_id));
create or replace function public.create_organization(p_name text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_actor uuid:=auth.uid(); v_org uuid; begin if v_actor is null then raise exception 'authentication required'; end if; if p_name is null or char_length(trim(p_name)) not between 2 and 120 then raise exception 'invalid organization name'; end if; insert into public.organizations(name) values(trim(p_name)) returning id into v_org; insert into public.memberships(organization_id,user_id,role) values(v_org,v_actor,'OWNER'); insert into public.audit_events(organization_id,actor_id,event_type,entity_type,entity_id,payload) values(v_org,v_actor,'ORGANIZATION_CREATED','organization',v_org,jsonb_build_object('name',trim(p_name))); return v_org; end $$;
create or replace function public.create_investment_project(p_organization_id uuid,p_name text,p_internal_reference text default null,p_description text default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_actor uuid:=auth.uid(); v_project uuid; begin if v_actor is null then raise exception 'authentication required'; end if; if not public.is_active_member(p_organization_id) then raise exception 'forbidden'; end if; if p_name is null or char_length(trim(p_name)) not between 2 and 160 then raise exception 'invalid project name'; end if; if p_internal_reference is not null and char_length(trim(p_internal_reference))>80 then raise exception 'invalid internal reference'; end if; if p_description is not null and char_length(trim(p_description))>2000 then raise exception 'invalid description'; end if; insert into public.investment_projects(organization_id,name,internal_reference,description) values(p_organization_id,trim(p_name),nullif(trim(p_internal_reference),''),nullif(trim(p_description),'')) returning id into v_project; insert into public.audit_events(organization_id,actor_id,event_type,entity_type,entity_id,payload) values(p_organization_id,v_actor,'PROJECT_CREATED','investment_project',v_project,jsonb_build_object('name',trim(p_name),'sector','REAL_ESTATE')); return v_project; end $$;
revoke all on function public.create_organization(text) from public, anon; revoke all on function public.create_investment_project(uuid,text,text,text) from public, anon; grant execute on function public.create_organization(text), public.create_investment_project(uuid,text,text,text) to authenticated;
revoke all on public.organizations,public.memberships,public.investment_projects,public.audit_events from anon,authenticated; grant select on public.organizations,public.memberships,public.investment_projects,public.audit_events to authenticated;
